argv:
$ErrorActionPreference='SilentlyContinue';
Set-Location 'E:\WebAIBridge';
$head=(git rev-parse HEAD 2>$null);
$dirty=@(git status --porcelain=v1 2>$null);
$data='E:\WebAIBridge\app\data';
$cut=Join-Path $data 'projects-live-control-plane-cutover-r42.json';
$state=Join-Path $data 'state.json';
$sup=Join-Path $data 'supervisor-watchdog.json';
$cutj=$null;if(Test-Path $cut){$cutj=Get-Content $cut -Raw|ConvertFrom-Json}
$statej=$null;if(Test-Path $state){$statej=Get-Content $state -Raw|ConvertFrom-Json}
$supj=$null;if(Test-Path $sup){$supj=Get-Content $sup -Raw|ConvertFrom-Json}
$http=$null;try{$http=Invoke-RestMethod -Uri 'http://127.0.0.1:17448/api/projects/control-plane/cutover-r42/status' -TimeoutSec 2}catch{$http=[pscustomobject]@{error=$_.Exception.Message}}
[pscustomobject]@{
 head=$head;
 dirty=@($dirty);
 cutoverFileExists=(Test-Path $cut);
 cutover=[pscustomobject]@{
  status=$cutj.status;holdActive=$cutj.holdActive;preCutoverHead=$cutj.preCutoverHead;targetSha=$cutj.targetSha;rollbackManifest=$cutj.rollbackManifest;rollbackCommand=$cutj.rollbackCommand
 };
 lifecycle=[pscustomobject]@{mode=$statej.operatorLifecycle.mode;revision=$statej.operatorLifecycle.revision;changedBy=$statej.operatorLifecycle.changedBy};
 queuePaused=$statej.settings.paused;
 supervisor=[pscustomobject]@{
  enabled=$supj.enabled;mode=$supj.mode;allowAutonomousSend=$supj.allowAutonomousSend;autoContinueEnabled=$supj.autoContinueEnabled;migrationEnabled=$supj.migrationEnabled;sendProtectedDraftEnabled=$supj.sendProtectedDraftEnabled;highModeStrategy=$supj.highModeStrategy
 };
 http=$http
}|ConvertTo-Json -Depth 8 -Compress
